def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return None

    def safe_list(v):
        return v if isinstance(v, list) else []

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pos(observation.get("self_position")) or [0, 0]
    opp_pos = first_pos(observation.get("opponent_position")) or [0, 0]
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        target = corners[0]
        best = -1
        for c in corners:
            d = dist(c, opp_pos)
            if d > best:
                best = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "border_cells", "frontier_cells"):
            for item in safe_list(observation.get(key)):
                p = first_pos(item)
                if p is not None:
                    candidates.append(p)
        if not candidates:
            return step_toward(self_pos, opp_pos) if dist(self_pos, opp_pos) > 0 else [0, 0]
        best = candidates[0]
        best_score = None
        for c in candidates:
            score = dist(self_pos, c) * 2 - dist(opp_pos, c)
            if best_score is None or score < best_score:
                best_score = score
                best = c
        return step_toward(self_pos, best)

    resources = []
    for key in ("resources", "resource_positions", "targets", "food"):
        for item in safe_list(observation.get(key)):
            p = first_pos(item)
            if p is not None:
                resources.append(p)

    if resources:
        best = resources[0]
        best_score = None
        for r in resources:
            score = dist(self_pos, r)
            if observation.get("resource_collection_mode") == "denial":
                score -= dist(opp_pos, r) * 0.5
            if best_score is None or score < best_score:
                best_score = score
                best = r
        return step_toward(self_pos, best)

    return step_toward(self_pos, opp_pos) if env != "resource_collection" else [0, 0]

